// Place search for every place picker and the Weather screen's "Look up another city"
// (traveller fix F1, 2026-10-25). Two sources, one ranking:
//   * the curated weather anchors (WEATHER_SPOTS in js/weather.js, 165 cities), always loaded;
//   * the offline place list: towns, islands, villages, subdistricts and communes from GeoNames
//     (js/data/gazetteer.<cc>.js, generated by scripts/build-gazetteer.py), imported on first
//     use and precached by sw.js so it answers with no signal.
// At equal relevance a curated city comes first. A list entry that repeats a curated city (the
// same name within NEAR_CURATED_KM) is hidden, so "Koh Chang" offers the city guide once.
//
// A place from the list is NEVER added to WEATHER_SPOTS: those are the Nearby anchors, and the
// screens that look content up by city name read them (CLAUDE.md). A picked place is a
// spot-shaped object with `gz: true` ({ gz, country, city, lat, lng, local, prov, kind });
// spotKey() gives it a key with its coordinates, and setFocusSpot() in main.js pairs it with the
// nearest anchor.

import { WEATHER_SPOTS, spotKey } from './weather.js';
import { store } from './state.js';
import { haversineKm } from './util.js';
import { getCountry } from './data/regions.js';

// Other names a traveller types for a curated city (moved here from js/screens/weather.js).
const CITY_AKA = {
  'vi:Ho Chi Minh City': ['Saigon', 'HCMC'],
  'th:Bangkok': ['Krung Thep'],
  'kh:Sihanoukville': ['Kampong Som'],
  'vi:Ha Long': ['Halong Bay'],
};
// Forgives the usual differences: accents (Huế), case, punctuation, and Ko, Koh or Kaoh for an
// island (GeoNames writes "Ko Mak" in Thailand and "Kaôh" in Cambodia; travellers write "Koh").
export function foldPlace(s) {
  return String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[đĐ]/g, 'd')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/\b(koh|kaoh)\b/g, 'ko').trim();
}

// One edit apart (one letter added, dropped or changed): "Don Khone" is Don Khon and "Samloem" is
// Sanloem, the spellings travellers meet on signs and booking sites. Only words of FUZZY_MIN
// letters or more get this, so "Ko Mak" never turns into Ko Mai.
const FUZZY_MIN = 5;
function oneEdit(a, b) {
  if (a === b) return true;
  if (Math.abs(a.length - b.length) > 1) return false;
  let i = 0;
  while (i < a.length && i < b.length && a[i] === b[i]) i++;
  if (a.length === b.length) return a.slice(i + 1) === b.slice(i + 1);
  return a.length > b.length ? a.slice(i + 1) === b.slice(i) : a.slice(i) === b.slice(i + 1);
}
function nearWord(w, x) {
  return w.length >= FUZZY_MIN && (oneEdit(w, x) || oneEdit(w, x.slice(0, w.length)));
}

// Lower is better, and at each level the place's own name beats its other names, so "kratie"
// puts Kratie ahead of Sambor (Kratie) and Enter takes the one meant. A whole name one letter
// off ranks just after the names that start with what was typed ("chiang" finds Chiang Mai before
// Chang); every typed word starting a word of the name ranks 4, and with one letter off, 4.5.
function rankNames(c, fq, tq) {
  const own = c.tight[0], other = c.tight.slice(1);
  if (own === tq) return 0;
  if (other.includes(tq)) return 1;
  if (own.startsWith(tq)) return 2;
  const qw = fq.split(' ');
  const words = c.words;
  if (words.some((nw) => nw.length === qw.length && qw.every((w, k) => w === nw[k] || (w.length >= FUZZY_MIN && oneEdit(w, nw[k]))))) return 2.5;
  if (other.some((t) => t.startsWith(tq))) return 3;
  if (words.some((nw) => qw.every((w) => nw.some((x) => x.startsWith(w))))) return 4;
  if (words.some((nw) => qw.every((w) => nw.some((x) => x.startsWith(w) || nearWord(w, x))))) return 4.5;
  if (tq.length >= 3 && c.tight.some((t) => t.includes(tq))) return 5;
  return -1;
}
function tighten(names) { return names.map((n) => n.replace(/ /g, '')); }
function splitWords(names) { return names.map((n) => n.split(' ')); }

let cityIndex = null;
function rankCities(q) {
  const fq = foldPlace(q);
  if (!fq) return [];
  const tq = fq.replace(/ /g, '');
  if (!cityIndex) {
    cityIndex = WEATHER_SPOTS.map((s, i) => {
      const inBrackets = (s.city.match(/\(([^)]+)\)/) || [])[1];
      const names = [s.city.replace(/\(.*?\)/g, ''), inBrackets, ...(CITY_AKA[spotKey(s)] || [])]
        .filter(Boolean).map(foldPlace);
      return { s, i, names, tight: tighten(names), words: splitWords(names), country: foldPlace((getCountry(s.country) || {}).name) };
    });
  }
  const hits = [];
  for (const c of cityIndex) {
    let rank = rankNames(c, fq, tq);
    // A country's name lists its cities: the whole name ahead of the place list's look-alikes
    // ("laos" is not Lao Suea Kok), the start of one only after everything else.
    if (c.country === fq) rank = Math.min(rank < 0 ? 1.6 : rank, 1.6);
    else if (rank < 0 && fq.length >= 3 && c.country.startsWith(fq)) rank = 6;
    if (rank >= 0) hits.push({ rank, s: c.s, i: c.i, c });
  }
  // Ties go to the hubs, then to the list's own order, which names each country's main
  // cities first (so "laos" leads with Vientiane, not alphabetically with Luang Prabang).
  hits.sort((a, b) => a.rank - b.rank || (b.s.hub ? 1 : 0) - (a.s.hub ? 1 : 0) || a.i - b.i);
  return hits;
}
// The curated cities only, best first.
export function findCities(q) { return rankCities(q).map((x) => x.s); }

// ---- THE OFFLINE PLACE LIST ------------------------------------------------------------------
// Explicit loaders, one per country, so the import guards can see each file.
const LIST_LOADERS = {
  th: () => import('./data/gazetteer.th.js'),
  vi: () => import('./data/gazetteer.vi.js'),
  kh: () => import('./data/gazetteer.kh.js'),
  la: () => import('./data/gazetteer.la.js'),
};
export const KIND_LABEL = { t: 'Town', i: 'Island', v: 'Village', s: 'Subdistrict', m: 'Commune' };
const NEAR_CURATED_KM = 25;
let listIndex = null;
let listLoading = null;

function parseList(cc, mod) {
  return mod.ROWS.split('\n').map((line, i) => {
    const [name, local, lat, lng, prov, kind, aka] = line.split('\t');
    const names = [name, ...(aka ? aka.split(';') : [])].map(foldPlace);
    return {
      cc, i, name, local: local || '', lat: Number(lat), lng: Number(lng),
      prov: prov ? (mod.PROVINCES[Number(prov)] || '') : '', kind: kind || 'v', names, tight: tighten(names), words: splitWords(names),
    };
  });
}
export function placeListReady() { return !!listIndex; }
// Resolves true once all four countries are in memory, false if they could not be loaded
// (offline before the service worker ever stored them); a later call tries again.
export function loadPlaceList() {
  if (listIndex) return Promise.resolve(true);
  if (!listLoading) {
    listLoading = Promise.all(Object.entries(LIST_LOADERS).map(([cc, load]) => load().then((m) => parseList(cc, m))))
      .then((parts) => { listIndex = parts.flat(); return true; })
      .catch(() => { listLoading = null; return false; });
  }
  return listLoading;
}

export function listSpot(e) {
  return { gz: true, country: e.cc, city: e.name, lat: e.lat, lng: e.lng, local: e.local, prov: e.prov, kind: e.kind };
}
export function placeLabel(s) {
  const c = getCountry(s.country) || {};
  const name = s.local ? `${s.city} · ${s.local}` : s.city;
  return c.flag ? `${c.flag} ${name}` : name;
}
export function placeSub(s) {
  const c = getCountry(s.country) || {};
  if (!s.gz) return c.name || s.country;
  return [KIND_LABEL[s.kind] || 'Place', s.prov].filter(Boolean).join(' · ');
}

// Curated cities and list places for one query, best first: { results, more }. `results` holds
// at most `limit` { key, spot } entries; `more` counts the matches left out.
export function findPlaces(q, limit = 6) {
  const cities = rankCities(q);
  const out = cities.map((x) => ({ rank: x.rank, src: 0, ord: x.i, spot: x.s }));
  const fq = foldPlace(q);
  const raw = String(q || '').trim();
  const tq = fq.replace(/ /g, '');
  const script = /[^\u0000-\u024f]/.test(raw);
  if (listIndex && (fq || script)) {
    for (const e of listIndex) {
      let rank = fq ? rankNames(e, fq, tq) : -1;
      if (rank < 0 && script && e.local) rank = e.local === raw ? 0 : e.local.startsWith(raw) ? 2 : e.local.includes(raw) ? 5 : -1;
      if (rank < 0) continue;
      const dup = cities.some((x) => x.s.country === e.cc && x.c.tight.includes(e.tight[0])
        && haversineKm({ lat: e.lat, lng: e.lng }, { lat: x.s.lat, lng: x.s.lng }) < NEAR_CURATED_KM);
      if (!dup) out.push({ rank, src: 1, ord: e.i, e });
    }
  }
  out.sort((a, b) => a.rank - b.rank || a.src - b.src || a.ord - b.ord);
  const results = out.slice(0, limit).map((x) => {
    const spot = x.spot || listSpot(x.e);
    return { key: spotKey(spot), spot };
  });
  return { results, more: Math.max(0, out.length - limit) };
}

// ---- RESOLVING A PICKED PLACE BY KEY ---------------------------------------------------------
// The pickers keep their onChange(key) contract, so a picked list place is remembered here first
// and spotForKey() (js/ui-widgets.js) finds it again; after a reload, the focused place comes
// back from the store (prefs.focusPlace, written by setFocusSpot in main.js).
const picked = new Map();
export function rememberPlace(spot) {
  if (spot && spot.gz) picked.set(spotKey(spot), spot);
  return spot;
}
export function placeForKey(key) {
  if (!key) return null;
  if (picked.has(key)) return picked.get(key);
  const p = store.profile.prefs.focusPlace;
  return p && spotKey(p) === key ? p : null;
}
